# -*- coding: utf-8 -*-
"""build_inventory — 技能侦察索引清单构建器（2026-09-14）
用法: py -X utf8 build_inventory.txt [extract|merge|all]
  extract: 遍历 ../源码/<repo> 的 SKILL.md，产出 stats.json + fragments.md
  merge:   主体(索引清单_主体.md, 含 [[INCLUDE:repo]] 占位) + fragments → ../索引清单.md
"""
import json, re, sys
from pathlib import Path

HERE = Path(__file__).resolve().parent
ROOT = HERE.parent
SRC = ROOT / "源码"
BUILD = HERE / "_build"

def parse_frontmatter(text):
    if not text.startswith("---"):
        return {}
    end = text.find("\n---", 3)
    if end < 0:
        return {}
    block = text[3:end].splitlines()
    fm, key, mode = {}, None, None
    for line in block:
        if not line.strip():
            continue
        m = re.match(r"^([A-Za-z_-]+):\s*(.*)$", line)
        if m and not line.startswith((" ", "\t")):
            key, val = m.group(1).lower(), m.group(2).strip()
            if val in ("|", "|-", ">", ">-", "|+", ">+"):
                fm[key] = ""
                mode = key
            else:
                fm[key] = val
                mode = None
        elif key is not None and line.startswith((" ", "\t")) and mode:
            fm[mode] = (fm[mode] + " " + line.strip()).strip()
    return fm

def norm(s, limit=110):
    s = re.sub(r"\s+", " ", s or "").strip()
    if len(s) > limit:
        cut = limit
        for p in ("。", "；", ";", ".", "！"):
            i = s.find(p, 40)
            if 0 < i < limit + 30:
                cut = min(cut, i + 1)
                break
        s = s[:cut].rstrip("，,、 ") + "…"
    return s

def detect_license(repo):
    for pat in ("LICENSE*", "LICENCE*", "COPYING*", "license*"):
        for f in repo.glob(pat):
            if f.is_file():
                try:
                    head = f.read_text("utf-8", errors="replace")[:400].upper()
                except Exception:
                    continue
                for tag, name in (("GNU AFFERO", "AGPL"), ("GNU GENERAL PUBLIC", "GPL"),
                                  ("APACHE LICENSE", "Apache-2.0"), ("MIT LICENSE", "MIT"),
                                  ("BSD", "BSD"), ("MOZILLA", "MPL"), ("UNLICENSE", "Unlicense")):
                    if tag in head:
                        return name
                return "有LICENSE(未见标准文本)"
    pj = repo / "package.json"
    if pj.exists():
        try:
            m = re.search(r'"license"\s*:\s*"([^"]+)"', pj.read_text("utf-8", errors="replace"))
            if m:
                return m.group(1)
        except Exception:
            pass
    return "未标注"

def tech_signals(repo):
    sig = []
    if (repo / "package.json").exists(): sig.append("package.json(Node)")
    if (repo / "pyproject.toml").exists(): sig.append("pyproject(Python)")
    if (repo / "requirements.txt").exists(): sig.append("requirements(Python)")
    if list(repo.glob("scripts/*.py")) or list(repo.rglob("scripts/**/*.py"))[:3]: sig.append("scripts/*.py")
    if list(repo.glob("scripts/*.js")) or list(repo.glob("scripts/*.ts")): sig.append("scripts/*.js|ts")
    if list(repo.glob("*.code-workspace")) or list(repo.glob(".claude")): sig.append(".claude/配置")
    return sig

def extract():
    BUILD.mkdir(parents=True, exist_ok=True)
    stats, frags = {}, []
    for repo in sorted([p for p in SRC.iterdir() if p.is_dir() and (p / ".git").exists()]):
        rows, seen = [], {}
        for f in sorted(repo.rglob("SKILL.md")):
            rel = f.parent.relative_to(repo).as_posix()
            try:
                fm = parse_frontmatter(f.read_text("utf-8", errors="replace"))
            except Exception:
                fm = {}
            name = fm.get("name") or f.parent.name
            desc = norm(fm.get("description", ""))
            if not desc:
                body = re.sub(r"^---.*?---", "", f.read_text("utf-8", errors="replace"), flags=re.S)
                desc = norm(re.sub(r"[#>*`]", "", body))
            if name in seen:
                continue
            seen[name] = True
            rows.append((name, desc, rel))
        rows.sort(key=lambda r: r[0].lower())
        stats[repo.name] = {
            "skills": len(rows),
            "license": detect_license(repo),
            "tech": tech_signals(repo),
        }
        lines = [f"#### 技能清单 · {repo.name}（{len(rows)} 个）", "",
                 "| 技能 | 一句话简历 | 位置 |", "|---|---|---|"]
        for n, d, rel in rows:
            loc = rel if rel != "." else "(仓库根)"
            d = d.replace("|", "\\|")
            lines.append(f"| `{n}` | {d} | {loc} |")
        frags.append(f"<!--FRAG:{repo.name}-->\n" + "\n".join(lines) + "\n")
    (BUILD / "stats.json").write_text(json.dumps(stats, ensure_ascii=False, indent=1), "utf-8")
    (BUILD / "fragments.md").write_text("\n".join(frags), "utf-8")
    print(json.dumps(stats, ensure_ascii=False, indent=1))

def merge():
    body = (ROOT / "索引清单_主体.md").read_text("utf-8")
    frags = (BUILD / "fragments.md").read_text("utf-8")
    table = {}
    for m in re.finditer(r"<!--FRAG:([\w.-]+)-->\n(.*?)(?=\n<!--FRAG:|\Z)", frags, re.S):
        table[m.group(1)] = m.group(2).strip()
    def sub(mm):
        return table.get(mm.group(1), f"> ⚠️ 片段缺失: {mm.group(1)}")
    out = re.sub(r"\[\[INCLUDE:([\w.-]+)\]\]", sub, body)
    (ROOT / "索引清单.md").write_text(out, "utf-8")
    print(f"merged -> {ROOT / '索引清单.md'} ({len(out)} chars)")

if __name__ == "__main__":
    act = sys.argv[1] if len(sys.argv) > 1 else "all"
    if act in ("extract", "all"): extract()
    if act in ("merge", "all"): merge()
